class Solution {
public:
    double myPow(double x, int n) {
        long long N = n;
        if (N < 0) {
            x = 1.0 / x;
            N = -N;
        }
        double result = 1.0;
        while (N) {
            if (N & 1LL) {
                result *= x;
            }
            x *= x;
            N >>= 1;
        }
        return result;
    }
};
